mapper.select:
/* QueryID=kkdugi.core.security.mapper.SecurityUserDetailsMapper.findByUsername */
SELECT
    user_id, user_login_id, user_pwd, user_nm, user_dc, user_img_src,
    last_login_dtm, last_chg_pwd_dtm, pwd_stat_cd, pwd_expr_dtm, user_stat_cd
FROM kkdugi_user_base
WHERE user_login_id = #{username}

mapper.update:
/* QueryID=kkdugi.core.security.mapper.SecurityUserDetailsMapper.updatePassword */
UPDATE kkdugi_user_base
SET user_pwd = #{password},
    upd_dtm  = CURRENT_TIMESTAMP
WHERE user_id = #{userId}

/* QueryID=kkdugi.core.security.mapper.SecurityUserDetailsMapper.updateLastLoginAt */
UPDATE kkdugi_user_base
SET last_login_dtm = #{lastLoginAt}
WHERE user_id = #{userId}

UPDATE kkdugi_user_base SET user_pwd = #{password}, pwd_stat_cd = '30',
    last_chg_pwd_dtm = #{changedAt}, pwd_expr_dtm = #{expiresAt},
    upd_dtm = CURRENT_TIMESTAMP, upd_id = #{userId}
WHERE user_id = #{userId}

UPDATE kkdugi_user_base SET pwd_stat_cd = '30', pwd_expr_dtm = #{expiresAt},
    upd_dtm = CURRENT_TIMESTAMP, upd_id = #{userId}
WHERE user_id = #{userId}
